def validate_topics(track_name, topics):
    print(f"Validating {len(topics)} {track_name} topics...")
    assert len(topics) == 100, f"Expected 100 {track_name} topics, got {len(topics)}"
    seen_names = set()
    for name, subject, system, focus, ref_name, ref_url in topics:
        assert name not in seen_names, f"Duplicate topic name: {name}"
        seen_names.add(name)
        assert subject in TAXONOMY_SUBJECTS, f"Invalid subject {subject} in {name}"
        assert system in TAXONOMY_SYSTEMS, f"Invalid system {system} in {name}"
        assert len(focus) >= 30, f"Focus too short in {name}"
        assert ref_url.startswith("https://"), f"Reference URL must start with https:// in {name}"
    print(f"Validated 100 {track_name} topics successfully.")

if __name__ == "__main__":
    validate_topics("MCCQE", MCCQE_RAW)
    validate_topics("NEET", NEET_RAW)
    if len(MRCP_RAW) == 100:
        validate_topics("MRCP", MRCP_RAW)
        out_content = f'''"""
Auto-generated topics for Mega-Batch 55 (Part B):
- 100 MCCQE (Canada) topics (1,700 -> 1,800)
- 100 NEET PG (India) topics (1,700 -> 1,800)
- 100 MRCP (UK) topics (1,700 -> 1,800)
"""

MCCQE_TOPICS = {repr(MCCQE_RAW)}

NEET_TOPICS = {repr(NEET_RAW)}

MRCP_TOPICS = {repr(MRCP_RAW)}
'''
        with open("scripts/mega55_topics_b.py", "w", encoding="utf-8") as f:
            f.write(out_content)
        print("Wrote scripts/mega55_topics_b.py successfully.")
    else:
        print(f"Waiting for MRCP_RAW (currently {len(MRCP_RAW)} topics). Run append_mrcp_55.py first.")
